    std::uint64_t *aOASaltF = pDomainSaltSet->mOrbiterAssign.mSaltF;
    std::uint64_t *aOASaltG = pDomainSaltSet->mOrbiterAssign.mSaltG;
    std::uint64_t *aOASaltH = pDomainSaltSet->mOrbiterAssign.mSaltH;
    std::uint64_t *aOUSaltA = pDomainSaltSet->mOrbiterUpdate.mSaltA;
    std::uint64_t *aOUSaltB = pDomainSaltSet->mOrbiterUpdate.mSaltB;
    std::uint64_t *aOUSaltC = pDomainSaltSet->mOrbiterUpdate.mSaltC;
    std::uint64_t *aOUSaltD = pDomainSaltSet->mOrbiterUpdate.mSaltD;
    std::uint64_t *aOUSaltE = pDomainSaltSet->mOrbiterUpdate.mSaltE;
    std::uint64_t *aOUSaltF = pDomainSaltSet->mOrbiterUpdate.mSaltF;
    std::uint64_t *aOUSaltG = pDomainSaltSet->mOrbiterUpdate.mSaltG;
    std::uint64_t *aOUSaltH = pDomainSaltSet->mOrbiterUpdate.mSaltH;
    std::uint64_t *aWUSaltA = pDomainSaltSet->mWandererUpdate.mSaltA;
    std::uint64_t *aWUSaltB = pDomainSaltSet->mWandererUpdate.mSaltB;
    std::uint64_t *aWUSaltC = pDomainSaltSet->mWandererUpdate.mSaltC;
    std::uint64_t *aWUSaltD = pDomainSaltSet->mWandererUpdate.mSaltD;
    std::uint64_t *aWUSaltE = pDomainSaltSet->mWandererUpdate.mSaltE;
