            aWandererK = aWandererK ^ (((RotL64(aScatter, 35U) + aOrbiterJ) + RotL64(aOrbiterD, 3U)) + aWUSaltB[(((511U - aIndex) + 416U)) & S_SALT1]);
            aWandererI = aWandererI + (((RotL64(aPrevious, 3U) + RotL64(aOrbiterC, 37U)) + aOrbiterB) + aWUSaltC[((aIndex + 168U)) & S_SALT1]);
