            aOrbiterG = ((aWandererG + RotL64(aScatter, 57U)) + 0x65A37BB1B520CFE8ULL) + aNonceWordN;
            aOrbiterB = (aWandererI + RotL64(aPrevious, 54U)) + 0xEF9E575942CF16FDULL;
            aOrbiterF = (aWandererH + RotL64(aCross, 39U)) + 0xC0BA28F8D51CC650ULL;
            aOrbiterI = ((((aWandererE + RotL64(aIngress, 27U)) + RotL64(aCarry, 23U)) + 0x40FDD62B3AAF73D0ULL) + aOASaltB[(((511U - aIndex) + 386U)) & S_SALT1]) + aNonceWordB;
            aOrbiterJ = (aWandererD + RotL64(aScatter, 43U)) + 0xF7BC7D8860318F37ULL;
            aOrbiterD = (aWandererJ + RotL64(aPrevious, 24U)) + 0xC96B5E2F8517DCD0ULL;
