            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0xF10AEEADE318610BULL;
            aOrbiterI = RotL64((aOrbiterI * 0x361241F1AEC77CE3ULL), 27U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterK) + 0xCBA95C5351A10960ULL) + aOUSaltC[((aIndex + 19U)) & S_SALT1];
