            aWandererI = aWandererI + ((RotL64(aIngress, 35U) + RotL64(aOrbiterE, 43U)) + aOrbiterC);
            aWandererF = aWandererF ^ (((RotL64(aScatter, 5U) + RotL64(aOrbiterG, 37U)) + aOrbiterD) + aWUSaltF[((aIndex + 97U)) & S_SALT1]);
            aWandererA = aWandererA + ((RotL64(aPrevious, 23U) + aOrbiterF) + RotL64(aOrbiterA, 58U));
            aWandererD = aWandererD ^ (((RotL64(aCross, 28U) + RotL64(aOrbiterI, 27U)) + aOrbiterH) + RotL64(aCarry, 29U));
            aWandererK = aWandererK + (((RotL64(aIngress, 21U) + RotL64(aOrbiterD, 35U)) + aOrbiterI) + aWUSaltE[((aIndex + 470U)) & S_SALT1]);
            aWandererE = aWandererE ^ ((RotL64(aScatter, 41U) + aOrbiterA) + RotL64(aOrbiterK, 19U));
            //
            aCarry = aCarry + (RotL64(aWandererK, 27U) ^ aWandererI);
            aCarry = aCarry + (aWandererB ^ RotL64(aWandererH, 13U));
            aCarry = aCarry + (RotL64(aWandererD, 30U) ^ aWandererA);
