            aOrbiterA = ((aOrbiterA ^ aOrbiterG) ^ 0x3C9EE71A587ED833ULL) ^ aOUSaltF[(((511U - aIndex) + 53U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xEA80EDF4A9E90A55ULL), 3U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterI) + 0xBB63C128987E50D2ULL) + aOUSaltB[(((511U - aIndex) + 508U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0xB9769ABB3D9C5A5AULL;
            aOrbiterC = RotL64((aOrbiterC * 0x7E385C25AB2CD259ULL), 23U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0xAA8C2F017DF510E4ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterE) ^ 0x3679166C79E9E599ULL) ^ aOUSaltD[(((511U - aIndex) + 284U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x316060BADA3C0C31ULL), 41U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterA) + 0x82289A7095465238ULL;
