            aWandererF = aWandererF + (((RotL64(aIngress, 43U) + aOrbiterC) + RotL64(aOrbiterA, 41U)) + aWUSaltC[((aIndex + 367U)) & S_SALT1]);
            aWandererI = aWandererI ^ ((RotL64(aScatter, 46U) + aOrbiterJ) + RotL64(aOrbiterI, 51U));
            aWandererA = aWandererA + ((RotL64(aPrevious, 51U) + RotL64(aOrbiterE, 11U)) + aOrbiterD);
            //
