            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterA = ((aWandererE + RotL64(aScatter, 21U)) + 0x77B2E25814832052ULL) + aOASaltC[((aIndex + 117U)) & S_SALT1];
            aOrbiterK = (aWandererA + RotL64(aPrevious, 29U)) + 0x692FA72F5DE12A04ULL;
            aOrbiterI = ((aWandererB + RotL64(aCross, 46U)) + RotL64(aCarry, 37U)) + 0x6DAB7E2A2C3DC2A9ULL;
