            aOrbiterG = (aWandererC + RotL64(aScatter, 43U)) + 0xD4E1D16984484BA2ULL;
            aOrbiterD = (((aWandererG + RotL64(aPrevious, 53U)) + RotL64(aCarry, 47U)) + 0xD44815F36BCC73A6ULL) + aOASaltH[(((511U - aIndex) + 347U)) & S_SALT1];
            aOrbiterE = (aWandererD + RotL64(aCross, 56U)) + 0x6D0D2F8F04AA5BB7ULL;
            aOrbiterJ = ((aWandererH + RotL64(aIngress, 39U)) + 0xB83ED24E5E363539ULL) + aOASaltF[((aIndex + 201U)) & S_SALT1];
            aOrbiterH = (aWandererK + RotL64(aScatter, 5U)) + 0x373D0C9645998B0BULL;
            aOrbiterF = ((aWandererF + RotL64(aPrevious, 41U)) + RotL64(aCarry, 13U)) + 0xAD10E7C2A09B95FDULL;
            aOrbiterC = (aWandererJ + RotL64(aCross, 23U)) + 0x41638C5643A211A6ULL;
