            aOrbiterA = (aOrbiterA + aOrbiterK) + 0xE60ECFAE83926CDCULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterA) ^ 0xF12A428207668942ULL) ^ aOUSaltD[(((511U - aIndex) + 62U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x0939C462C33DC929ULL), 11U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterG) + 0xD2C6471C9E83F62DULL) + aOUSaltC[(((511U - aIndex) + 326U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0xE032A4746855A22EULL;
            aOrbiterD = RotL64((aOrbiterD * 0x76DF173F9701D17FULL), 21U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0x2669BC0B98ED3562ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterE) ^ 0xEA11092C6B525DE4ULL) ^ aOUSaltE[((aIndex + 267U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xBB57A43F53A6C2C9ULL), 35U);
            //
