            aOrbiterA = (((aWandererI + RotL64(aScatter, 19U)) + RotL64(aCarry, 39U)) + 0x391F5D3C15ED2E5FULL) + aOASaltC[((aIndex + 439U)) & S_SALT1];
            aOrbiterB = (aWandererH + RotL64(aPrevious, 35U)) + 0x855AB70F6858F433ULL;
            aOrbiterD = ((aWandererF + RotL64(aCross, 47U)) + 0x1563026936D2A9BAULL) + aOASaltA[(((511U - aIndex) + 177U)) & S_SALT1];
            aOrbiterJ = ((aWandererA + RotL64(aIngress, 58U)) + 0xF36F7E3DF35B8B25ULL) + aOASaltG[((aIndex + 73U)) & S_SALT1];
