            aOrbiterG = RotL64((aOrbiterG * 0xE1C09C327A549925ULL), 41U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterD) + 0x766917A0321388FBULL) + aOUSaltD[(((511U - aIndex) + 507U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0x63B82D44EE8E8B08ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xAF22DBC8B24E57BBULL), 47U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0x84EAE543C04B35CCULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0x79F2EA9274A31F87ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x10CC50E812091B13ULL), 3U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0xF25AE25E2D181044ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterH) ^ 0x71AFAE710485043FULL) ^ aOUSaltA[((aIndex + 379U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x4EFE793222C14CF5ULL), 37U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterF) + 0x193692D228470A2CULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0x6922F69EB8F9DD67ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x6614679C158FDE4FULL), 29U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0x24A8A33163478268ULL;
