            aCross ^= (RotL64(aWaterLaneD[((S_BLOCK1 - aIndex + 9492U)) & S_BLOCK1], 21U) ^ RotL64(aMagmaLaneA[((aIndex + 15556U)) & S_BLOCK1], 60U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
