            aScatter = (RotL64(aPrevious, 56U) + RotL64(aCross, 19U)) + (RotL64(aCarry, 5U) ^ RotL64(aIngress, 41U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterH = (aWandererI + RotL64(aScatter, 44U)) + 0xF1A8595D26634AE9ULL;
            aOrbiterB = (aWandererA + RotL64(aPrevious, 41U)) + 0x469331650D1C1B5AULL;
            aOrbiterE = (((aWandererG + RotL64(aCross, 13U)) + RotL64(aCarry, 27U)) + 0x817C3E7DDDB1C516ULL) + aOASaltA[(((511U - aIndex) + 343U)) & S_SALT1];
            aOrbiterF = ((aWandererD + RotL64(aIngress, 21U)) + 0x5061A775173AA099ULL) + aOASaltD[(((511U - aIndex) + 159U)) & S_SALT1];
            aOrbiterK = (aWandererF + RotL64(aScatter, 51U)) + 0xCAA771B9F2E886FAULL;
            aOrbiterA = (aWandererE + RotL64(aPrevious, 18U)) + 0xF232E3D9BAE2E544ULL;
            aOrbiterI = ((aWandererC + RotL64(aCross, 37U)) + RotL64(aCarry, 37U)) + 0xCFE1F3F2DCED4894ULL;
            aOrbiterJ = ((aWandererJ + RotL64(aIngress, 39U)) + 0x21A45656DDF3D297ULL) + aOASaltH[(((511U - aIndex) + 218U)) & S_SALT1];
