            aWandererC = aWandererC ^ ((RotL64(aCross, 4U) + aOrbiterH) + RotL64(aOrbiterA, 51U));
            aWandererE = aWandererE + ((RotL64(aIngress, 51U) + RotL64(aOrbiterG, 56U)) + aOrbiterK);
            //
