            aIngress = (RotL64(aAetherLaneA[((aIndex + 10052U)) & S_BLOCK1], 54U) ^ RotL64(aVaporLaneC[((aIndex + 14921U)) & S_BLOCK1], 43U));
            aIngress ^= (RotL64(aPlasmaLaneC[((aIndex + 8868U)) & S_BLOCK1], 19U) ^ RotL64(aCrystalLaneC[((S_BLOCK1 - aIndex + 9396U)) & S_BLOCK1], 11U));
