            aWandererG = aWandererG + ((RotL64(aScatter, 51U) + aOrbiterB) + RotL64(aOrbiterE, 47U));
            aWandererF = aWandererF ^ ((RotL64(aPrevious, 39U) + RotL64(aOrbiterH, 60U)) + aOrbiterD);
            aWandererI = aWandererI + (((RotL64(aCross, 41U) + aOrbiterI) + RotL64(aOrbiterC, 51U)) + aWUSaltE[(((511U - aIndex) + 38U)) & S_SALT1]);
