            aWandererG = aWandererG + (((RotL64(aPrevious, 48U) + RotL64(aOrbiterF, 43U)) + aOrbiterE) + RotL64(aCarry, 35U));
            aWandererH = aWandererH ^ (((RotL64(aCross, 21U) + aOrbiterA) + RotL64(aOrbiterI, 39U)) + aWUSaltD[((aIndex + 6U)) & S_SALT1]);
