            aCross = (RotL64(aVaporLaneC[((S_BLOCK1 - aIndex + 7710U)) & S_BLOCK1], 51U) ^ RotL64(aVaporLaneD[((S_BLOCK1 - aIndex + 1531U)) & S_BLOCK1], 39U));
            aCross ^= (RotL64(aKineticLaneC[((S_BLOCK1 - aIndex + 23U)) & S_BLOCK1], 4U) ^ RotL64(aCrystalLaneA[((aIndex + 4095U)) & S_BLOCK1], 13U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateBDomainWordCross));
