            aScatter = (RotL64(aCarry, 21U) ^ RotL64(aIngress, 53U)) ^ (RotL64(aPrevious, 34U) + RotL64(aCross, 5U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterJ = (aWandererI + RotL64(aIngress, 27U)) + 0x690164B931104F4DULL;
            aOrbiterC = (aWandererE + RotL64(aScatter, 57U)) + 0x4A81638EB6EF7657ULL;
            aOrbiterG = ((aWandererA + RotL64(aPrevious, 5U)) + 0xA2C3864303EB6AC1ULL) + aOASaltC[((aIndex + 398U)) & S_SALT1];
            aOrbiterB = ((aWandererD + RotL64(aCross, 47U)) + RotL64(aCarry, 47U)) + 0x2BBC7A53560FE701ULL;
            aOrbiterF = (aWandererH + RotL64(aIngress, 44U)) + 0x6734B9F7712D47D7ULL;
