            aOrbiterI = (aWandererJ + RotL64(aPrevious, 39U)) + 0xF7D0D18F7B5BCDE5ULL;
            aOrbiterA = (((aWandererK + RotL64(aCross, 35U)) + RotL64(aCarry, 53U)) + 0x44E2B33416AA44D4ULL) + aOASaltH[((aIndex + 379U)) & S_SALT1];
            aOrbiterE = ((aWandererG + RotL64(aIngress, 42U)) + 0xA505629C5119CF4CULL) + aOASaltA[((aIndex + 394U)) & S_SALT1];
            aOrbiterK = (aWandererC + RotL64(aScatter, 23U)) + 0x0931257A37613383ULL;
            aOrbiterH = ((aWandererF + RotL64(aPrevious, 51U)) + RotL64(aCarry, 11U)) + 0x9F4A2AA3C86CCE47ULL;
